namespace EndfieldChargePlus.Settings;

internal sealed record ManualText(string Zh,string En,string? Localized=null)
{
    internal string Value=>Localized ?? LocalizationManager.Text(Zh,En);
    public override string ToString()=>Value;
}
internal sealed record ManualBlock(string Id,ManualText Title,ManualText Body,string Kind="text",string Code="",string? Target=null);
internal sealed record ManualChapter(string Id,ManualText Title,ManualText Summary,IReadOnlyList<ManualBlock> Blocks)
{
    internal bool Matches(string query)=>string.IsNullOrWhiteSpace(query) ||
        (Title.Zh+" "+Title.En+" "+Title.Value+" "+Summary.Zh+" "+Summary.En+" "+Summary.Value+" "+string.Join(" ",Blocks.Select(b=>b.Title.Zh+" "+b.Title.En+" "+b.Title.Value+" "+b.Body.Zh+" "+b.Body.En+" "+b.Body.Value+" "+b.Code))).Contains(query,StringComparison.OrdinalIgnoreCase);
}
internal static class UserManualContent
{
    internal const string HttpExample="""
[
  {
    "name": "demo",
    "enabled": false,
    "url": "https://example.com/status",
    "refreshSeconds": 10,
    "headers": { "Authorization": "Bearer ${env:MY_API_KEY}" },
    "fields": [
      { "variable": "value", "jsonPath": "data.value" },
      { "variable": "name", "jsonPath": "players[0].name" }
    ]
  }
]
""";
    private static ManualBlock B(string id,string title,string enTitle,string body,string enBody,string kind="text",string code="",string? target=null)=>new(id,new(title,enTitle),new(body,enBody),kind,code,target);
    private static ManualChapter C(string id,string title,string enTitle,string summary,string enSummary,params ManualBlock[] blocks)=>new(id,new(title,enTitle),new(summary,enSummary),blocks);
    internal static IReadOnlyList<ManualChapter> Chapters=>PlatformManualContent.Adapt(NativeManualContent.Localize(BaseChapters));
    private static IReadOnlyList<ManualChapter> BaseChapters {get;}=new[] {
        C("start","快速开始","Getting started","先完成一次显示，再逐步定制。","Get a HUD on screen, then customize it.",
            B("first-hud","三步显示 HUD","Show your first HUD","在“显示与位置”开启 HUD 总开关；需要持续显示时开启“一直显示”。\n在“HUD显示内容 → HUD 配置”选择一个内置方案，点击“预览当前方案”查看效果。\n点击右上角“保存并应用”，让当前编辑的设置进入实际运行。","Enable the HUD Master Switch under Display & Position; turn on Always Visible for a persistent HUD.\nChoose a built-in profile under HUD Content → HUD Configuration and preview it.\nClick Save & Apply at the top right to apply the settings to the running HUD.","steps",target:"hud"),
            B("save-levels","方案保存与保存并应用","Profile Save vs. Save & Apply","方案旁的“保存”记录编辑中的方案；修改内置方案会另存为自定义方案。“预览”只查看当前编辑效果。右上角“保存并应用”才会保存整套设置并应用到运行中的 HUD。","Save beside the profile records the edited profile; editing a built-in creates a custom copy. Preview shows the current edit. Save & Apply at the top right saves the full settings and applies them to the running HUD."),
            B("navigation","设置在哪里","Find the right page","显示与位置：显隐、位置、外观与采样。HUD显示内容：方案、轮播与触发规则。数据管理：变量库、硬件数据、数据源配置。实验性功能：多 HUD。关于：更新、备份与维护。","Display & Position: visibility, placement, appearance and sampling. HUD Content: profiles, cycling and trigger rules. Data Management: Variable Library, Hardware Data and Data Source Configuration. Experimental Features: multiple HUDs. About: updates, backup and maintenance.")),
        C("display","显示、位置与外观","Display, position & appearance","理解两种显示模式及屏幕坐标。","Understand display modes and screen coordinates.",
            B("language","界面语言与跟随系统","Interface language and system default","在窗口顶部的语言列表选择所需语言，或选择“跟随系统”。切换会立即保存语言偏好，其他未保存的设置仍需点击“保存并应用”。不支持的系统语言回退为英语。语言选择会应用到设置、内置方案、数据提示与使用手册；变量键、公式和接口 JSON 不会翻译。","Choose a language in the top bar, or select Follow system. The language preference is saved immediately; other pending edits still require Save & Apply. Unsupported system languages fall back to English. Settings, built-in profiles, data warnings and this manual follow the language. Variable keys, formulas and API JSON remain unchanged."),
            B("modes","常驻与临时显示","Persistent and transient modes","“一直显示”开启后 HUD 保持可见，可选择始终置顶或桌面层。关闭后按电源事件、鼠标热区或触发规则临时呼出，经过显示时长后收回。总开关关闭会停止显示；应用下次启动时总开关会恢复开启。","Always Visible keeps the HUD on screen with an Always on Top or Desktop layer. With it off, power events, the mouse hot zone or trigger rules summon it temporarily, then retract it after the display duration. Turning off the Master Switch stops display for the session; the switch is re-enabled on the next app launch.",target:"display"),
            B("coordinates","工作区与完整屏幕","Work area vs. full screen","工作区预设避开任务栏、Dock 等系统保留区域；“屏幕…”预设按完整显示器边界定位。微调在预设基础上移动；自定义坐标直接指定位置。先选目标显示器，再调整位置。多显示器位于主屏左侧或上方时，负坐标是正常的。","Work-area presets avoid taskbars, Docks and reserved regions. Screen presets use full display bounds. Offsets move a preset; custom coordinates specify the position directly. Select the target display first. Negative coordinates are normal for displays left of or above the primary display."),
            B("appearance","大小、透明度、字体与动效","Size, opacity, fonts and motion","全局缩放调整整枚 HUD 的大小；不透明度决定可见程度。字体选择影响显示文字，系统默认会补全缺失字符。显示时长控制临时模式的停留；弹跳、波纹强度与扩散影响动画外观。“重置大小与动画”会还原该组参数，随后仍需保存并应用。","Global Scale changes the whole HUD size; opacity controls its visibility. Font selection changes text rendering, with system fallback for missing glyphs. Display duration controls transient hold time; bounce and ripple controls change motion appearance. Reset Size & Animation restores this group of values; use Save & Apply afterwards."),
            B("sampling","采样间隔与数据新鲜度","Sampling and freshness","采样间隔由所有 HUD 共用，越短资源消耗越高。时钟按秒更新；HTTP、余额查询等外部来源仍有各自的缓存或刷新间隔。把全局采样设得更快，不会绕过外部数据源的缓存。","All HUDs share one sampling interval; shorter intervals use more resources. Clocks update by seconds, while HTTP and balance sources keep their own refresh/cache intervals. Faster global sampling does not bypass a source's cache.")),
        C("profiles","方案与 HUD 内容","Profiles & HUD content","决定 HUD 显示什么，以及如何呈现。","Choose what the HUD shows and how it looks.",
            B("profile-actions","新建、保存、删除与预览","Create, save, delete and preview","选择内置方案作为起点，修改后点击方案旁的“保存”会建立自定义副本。也可新建空白方案。删除用于清理自定义方案；内置原始预设保留。预览使用当前编辑内容和真实数据；保存并应用后实际 HUD 才采用新配置。","Start from a built-in profile and Save to create a custom copy, or create a new profile. Delete removes custom profiles while original presets remain. Preview uses the current edit and real data; Save & Apply commits it to the running HUD.",target:"hud"),
            B("text-fields","文字区域与图标","Text regions and icons","顶部标记、标题、左侧主值/次值和右侧数值都可以混合普通文字与变量模板。右侧后缀适合放 %、°C、GHz 等单位。左右图标用于标识内容；强调色控制胶囊与圆环的主题颜色。","Tagline, title, primary/secondary text and the right-side value can mix literal text and variable tokens. Use the right suffix for units such as %, °C or GHz. Icons identify the content; the accent color sets the capsule and ring color."),
            B("progress","圆环的变量与量程","Ring variable and range","圆环按“当前值 − 最小值”相对整个量程计算比例，并限制在 0–100%。变量本身可使用原始变量名或 = 开头的数值表达式。温度、网速、帧率等应设置适合自己的最大值；量程不会改变文字显示的原始读数。","The ring maps (value − minimum) over the configured range, clamped to 0–100%. Use a variable key or a numeric expression beginning with =. Set a sensible full-scale value for temperature, traffic or FPS. The range does not change the raw text reading.",code:"cpu.usage\n= (cpu.usage + gpu.usage) / 2"),
            B("color-rules","条件变色","Conditional colors","每行配置一个“变量 运算符 阈值 => 颜色”。规则用于按负载、温度等改变强调色；阈值使用该变量的原始单位。颜色必须是有效色值；缺失数据不会被当作 0 来匹配条件。","Add one variable/operator/threshold => color rule per line. Rules change the accent based on load, temperature and other values. Thresholds use the variable's original unit. Use valid color values; missing measurements are not treated as zero.",code:"cpu.usage >= 90 => #FF4D4F\ncpu.usage >= 75 => #FFB84D")),
        C("variables","变量、模板与表达式","Variables, tokens & expressions","从变量库复制，再组合成可读的 HUD。","Copy from the library, then build readable HUD text.",
            B("library","查找与复制变量","Find and copy a variable","在“数据管理 → 变量库”按名称、变量名或分类搜索。选择后查看含义、类型、单位和格式建议。“复制变量名”适合圆环变量或触发规则；“复制模板”得到带花括号的写法，适合文字区域。","Search by name, key or category under Data Management → Variable Library. Select a variable to see its meaning, type, unit and formats. Copy Variable Key is useful for rings and rules; Copy Template includes braces for text fields.",target:"variables"),
            B("format","常用模板格式","Common token formats","花括号中写变量名；竖线后接显示格式。0 表示整数，0.0 / 0.00 表示固定小数位。普通文字可写在模板两侧。数字格式只改变显示，不会改动数据源。","Place the key in braces, followed by | and a display format. Use 0 for integers and 0.0 / 0.00 for fixed decimals. Literal text may surround tokens. Formatting changes display only.",code:"CPU {cpu.usage|0.0}%\n{cpu.frequency_ghz|0.00} GHz\n{= (cpu.usage + gpu.usage) / 2 |0.0}%"),
            B("pipelines","自动单位与格式管道","Automatic units and pipelines","auto:1 根据变量含义选择单位；不要再重复添加同一单位。格式管道从左到右执行，既可转换数值，也可裁剪文字。进阶公式在 {= ...} 内使用，圆环公式则直接以 = 开头。","auto:1 chooses units based on the variable; avoid adding the same unit twice. Format pipelines run left to right and can transform numbers or shorten text. Use {= ...} for inline expressions, or start a ring expression with =.",code:"{network.download_bps|auto:1}\n{cpu.usage|math:round:1|0.0}"),
            B("operators","运算、比较与条件","Operators and conditions","支持 +、-、*、/、% 取余、^ 乘方和括号；比较可用 >、>=、<、<=、==、!=。逻辑可用 &&、||、!，也支持 and/or/not。条件表达式写作 条件 ? 成立值 : 否则值，或 if(条件, 成立值, 否则值)。用 ?? 为缺失/空值指定回退内容。","Use +, -, *, /, % remainder, ^ power and parentheses. Comparisons support >, >=, <, <=, == and !=. Boolean operators include &&, ||, ! and and/or/not. Conditions use test ? yes : no or if(test, yes, no). ?? supplies a fallback for null/empty values.",code:"{= cpu.usage >= 90 ? 'HIGH' : 'NORMAL'}\n{= clamp(cpu.usage, 0, 100)|0.0}"),
            B("numeric-functions","数值函数速查","Numeric function reference","聚合：min、max、avg、sum。范围与精度：clamp(值, 下限, 上限)、round(值, 小数位)、floor、ceil、abs、sign。数学：sqrt、pow、log、log10、exp、sin、cos、tan。percent(当前值, 总量) 计算百分比；between(值, 下限, 上限) 判断闭区间。","Aggregates: min, max, avg and sum. Range/precision: clamp(value, min, max), round(value, digits), floor, ceil, abs and sign. Math: sqrt, pow, log, log10, exp, sin, cos and tan. percent(value, total) returns a percentage; between(value, min, max) tests an inclusive range.",code:"{= avg(cpu.usage, gpu.usage)|0.0}\n{= percent(memory.used_bytes, memory.total_bytes)|0.0}"),
            B("text-functions","文字、类型与格式管道速查","Text, types and pipeline reference","表达式函数：len、contains、startswith、endswith、upper、lower、concat；类型转换：number、string、bool；检查：isnull、isempty、isnan。模板管道可用 upper/lower、sub:起点:长度（起点从 0 开始）、replace:原文:新文，以及 math:add/sub/mul/div/round/floor/ceil/abs。","Expression functions: len, contains, startswith, endswith, upper, lower and concat. Convert types with number, string or bool; inspect them with isnull, isempty and isnan. Token pipelines support upper/lower, zero-based sub:start:length, replace:old:new and math:add/sub/mul/div/round/floor/ceil/abs.",code:"{media.title|sub:0:24}\n{cpu.usage|math:div:100|0.00}"),
            B("units-time","容量与时间格式","Capacity and time formats","bytes / speed 自动显示字节容量或每秒速率；kb:n、mb:n、gb:n、tb:n 按 1024 换算并保留 n 位小数，单位后缀由你在方案中决定。duration 与 duration-long 将秒数转为时长。日期时间字段可用 time:日期格式；time:relative 可显示相对时间/时长。","bytes / speed add automatic byte-size or byte-rate units. kb:n, mb:n, gb:n and tb:n divide by powers of 1024 with n decimals; add the desired unit in the profile. duration / duration-long format seconds. Date/time fields support time:<date format>; time:relative formats relative time or duration.",code:"{memory.used_bytes|gb:2} GiB\n{battery.time_remaining_seconds|duration}"),
            B("duplicates","硬件变量与旧变量","Hardware variables and legacy keys","发现对应硬件项目后，重复的旧变量会从变量库移除，旧方案中的变量名仍可读取。新硬件变量指向明确设备和传感器；“最高温度”“平均温度”等汇总值具有不同含义，会单独保留。变量显示 -- 表示当前未取得有效数据。","Once equivalent hardware fields are discovered, duplicate legacy entries leave the library while existing profiles keep working. New keys identify a specific device and sensor. Highest/average summaries have different meanings and remain separate. -- means no valid value is currently available.")),
        C("hardware","硬件传感器与驱动","Hardware sensors & drivers","查看真实读数，处理温度与驱动问题。","Inspect real readings and resolve driver issues.",
            B("hardware-page","查看、搜索、复制与导出","Inspect, search, copy and export","在“数据管理 → 硬件数据”查看实际传感器与固件信息，可用“温度”“内存条”、设备名或原始 ID 搜索。选择项目后复制模板到 HUD。导出诊断会保存本地 JSON，便于查看当时的状态和读数。","Use Data Management → Hardware Data to inspect sensors and firmware fields. Search by temperature, memory module, device name or original ID. Select a row to copy its token. Export Diagnostics saves a local JSON snapshot of the current status and readings.",target:"hardware"),
            B("pawnio","CPU 温度仍是 --","CPU temperature still shows --","查看页面顶部的驱动状态。缺少 PawnIO 时点击安装/更新驱动并完成 Windows UAC；安装后完全退出 ECP。\n以管理员身份重新启动 ECP，再查看温度。页面的重启按钮会处理旧进程退出。\n若仍不可用，查看“驱动无法访问”或“硬件未返回数据”的具体状态，并导出诊断。","Read the driver status at the top. If PawnIO is missing, install/update it and complete Windows UAC; fully exit ECP afterwards.\nRestart ECP as administrator and check again. The restart button waits for the old process to exit.\nIf it remains unavailable, distinguish inaccessible-driver status from hardware returning no data, then export diagnostics.","steps"),
            B("raw-sensors","独立传感器与汇总","Individual sensors and summaries","同一台 CPU/GPU 可能有封装、核心、热点、显存或多个功耗通道，名称相近也不一定重复。最小/最大值是上游监控会话记录，不是硬件规格上限。SMBIOS 内存条信息来自固件，不等于完整 SPD/XMP/EXPO 时序表。","One CPU/GPU may expose package, core, hotspot, memory and multiple power channels. Similar names can represent different measurements. Sensor min/max values are session history, not hardware limits. SMBIOS module information comes from firmware and is not a complete SPD/XMP/EXPO timing table.")),
        C("sources","数据源配置","Data source configuration","连接 DeepSeek、HTTP JSON 与 AIDA64。","Connect DeepSeek, HTTP JSON and AIDA64.",
            B("deepseek","DeepSeek API 余额与峰谷","DeepSeek balance and peak periods","在“数据管理 → 数据源配置”填写 DeepSeek API Key，再保存并应用。Key 使用 Windows 当前用户加密存储；跨用户或换机器后可能需要重新填写。高峰窗口按北京时间显示，结合中国节假日日历判断；周末补班仍为低谷。","Enter a DeepSeek API key under Data Management → Data Source Configuration, then Save & Apply. Keys are encrypted for the current Windows user and may need re-entry for another account or machine. Peak windows use Beijing time and the Chinese holiday calendar; weekend make-up workdays remain off-peak.",target:"sources"),
            B("http","HTTP / JSON 的配置步骤","Configure HTTP / JSON","填写返回 JSON 的 HTTP/HTTPS GET 地址，给数据源一个名称。\n把响应中的字段路径映射到变量名；例如 data.value 或 players[0].name。\n按接口要求设置请求头与刷新秒数，启用数据源后保存并应用。\n在变量库找到 custom.<数据源名>.<变量名>，复制到方案。","Enter an HTTP/HTTPS GET URL that returns JSON and name the source.\nMap response paths such as data.value or players[0].name to variable names.\nSet required headers and refresh seconds, enable the source, then Save & Apply.\nFind custom.<source>.<variable> in the library and use it in a profile.","steps"),
            B("http-example","可复制的 JSON 结构","Copyable JSON structure","下面是未启用的结构示例。将地址替换为自己的真实接口，并按实际响应调整字段路径；确认后将 enabled 改为 true。${env:MY_API_KEY} 从进程环境变量读取，不需要把敏感值直接写进 JSON。","This structure is disabled. Replace the URL with your real endpoint, adjust paths to the response and set enabled to true when ready. ${env:MY_API_KEY} reads a process environment variable instead of putting a secret directly in JSON.",code:HttpExample),
            B("http-errors","状态、缓存与故障","Status, cache and errors","custom.<源名>.status / error 用于查看来源状态或错误。刷新间隔决定缓存多久；全局采样更快不代表接口会每次重查。401/403 通常需要检查鉴权或访问权限；JSON 路径必须与真实返回结构一致。","Use custom.<source>.status / error for source state and failures. The refresh interval controls caching, even with faster global sampling. For 401/403, check authentication and access. JSON paths must match the actual response structure."),
            B("aida64","AIDA64 外部程序接口","AIDA64 external applications","在 AIDA64 的“设置 → 硬件监控 → 外部程序”勾选需要导出的项目，并开启共享内存、注册表或 WMI。保持 AIDA64 运行，再到 ECP 硬件数据页重新检测。ECP 读取实际导出的全部项目，包含数值、内存时序和文本；未导出或许可证限制的项目不会生成有效读数。","In AIDA64 Preferences → Hardware Monitoring → External Applications, select the items and enable shared memory, Registry or WMI. Keep AIDA64 running, then refresh ECP Hardware Data. ECP reads all actual exports, including numbers, timings and text; unexported or license-limited fields remain unavailable.",target:"hardware")),
        C("cycle","轮播、点击与动画","Cycling, clicks & animations","控制多个方案如何轮流显示。","Control how profiles alternate.",
            B("queue","建立自己的轮播队列","Build a carousel queue","将需要的方案加入队列，用上移/下移调整顺序；移出队列不会删除方案。开启自动轮播后按间隔切换。队列为空时使用当前方案；只有一个项目时不会切换到另一个方案。","Add profiles to the queue and use Move Up/Down to order them. Removing from the queue does not delete the profile. Automatic cycling advances at the configured interval. An empty queue uses the active profile; a single-item queue cannot switch to a different item.",target:"hud"),
            B("animation","三种轮播动画","Three cycle animations","简洁：缩短显示过程。完整：播放完整呼出过程。向上翻滚：在常驻胶囊内部滚动图标、数值、圆环等内容，保持窗口与层级。翻滚适用于常驻切换；首次显示和临时呼出仍保留正常显示/收回生命周期。DeepSeek 峰谷事件保留完整动画。","Simple shortens the presentation; Full uses the complete summon. Roll Up moves icons, values and the ring inside a persistent capsule while retaining its window and layer. Roll applies to persistent switches; initial and transient presentations keep their normal show/retract lifecycle. DeepSeek peak transitions keep Full animation."),
            B("click-cycle","点击常驻 HUD 切换","Click a persistent HUD to switch","开启点击切换后，即使没有开启自动轮播，也能按队列点击切换。点击哪个 HUD 就切换哪个实例，且重置它的自动轮播计时。透明区域仍允许鼠标操作后方应用。空队列或单项队列不会切换。","Enable click cycling to advance through the queue even with automatic cycling off. Each HUD advances its own instance and resets its cycle timer. Transparent areas remain click-through. Empty or single-item queues do not switch.")),
        C("summons","快捷键与鼠标热区","Shortcuts & mouse hot zones","主动显示或暂时隐藏 HUD。","Summon or temporarily hide the HUD.",
            B("shortcut","设置显示/隐藏快捷键","Set a show/hide shortcut","点击快捷键输入框，按 Ctrl 或 Alt 加字母、数字或功能键，再保存并应用。F12 和保留组合不接受；若组合已被占用，界面会提示，原快捷键保持不变。清空并保存可关闭快捷键。","Focus the shortcut box and press Ctrl or Alt with a letter, digit or function key, then Save & Apply. F12 and reserved combinations are rejected. If registration conflicts, the previous shortcut remains active. Clear and save to disable it.",target:"display"),
            B("shortcut-animation","显隐动画与作用范围","Visibility animation and scope","快捷键显示动画可独立选择完整或简洁；隐藏先播放收回动画。它控制全部 HUD，保留各自的方案与位置；临时模式会呼出一次后继续原有事件行为。快速连按以最后一次请求为准。快捷键隐藏状态仅用于当前会话。","Choose Full or Simple reveal animation for the shortcut; hiding plays a retract animation. It affects all HUDs while retaining their profiles and positions. In transient mode it summons once, then resumes event behavior. The latest rapid request wins. Shortcut suppression lasts for the session."),
            B("hot-zone","配置热区的位置与停留","Configure hot-zone position and dwell","关闭“一直显示”后可启用热区。选择九宫格位置、宽高、偏移与停留时间；热区按目标屏幕完整边界计算，超出部分会限制在屏幕内。停留达到设定时间才呼出；离开再进入可再次触发。也可开启每次呼出推进轮播队列。","Hot zones are available with Always Visible off. Set the anchor, size, offsets and dwell time. The region uses full target-display bounds and is clamped to the screen. Dwell for the chosen interval to summon; leave and re-enter to re-arm. You may advance the carousel on each summon.")),
        C("triggers","事件触发规则","Event trigger rules","让数据变化自动呼出对应 HUD。","Summon a HUD when data meets a rule.",
            B("create-rule","添加一条规则","Add a rule","在“HUD显示内容 → 触发规则”添加规则并启用。\n填写变量名，选择阈值、取值变化或由假变真；阈值模式再设置运算符和数值。\n填写冷却时间，关闭“一直显示”，保存并应用。","Add and enable a rule under HUD Content → Trigger Rules.\nEnter a variable key and choose Threshold, Change or Becomes True; configure the operator and value for thresholds.\nSet a cooldown, turn Always Visible off, then Save & Apply.","steps",target:"rules"),
            B("rule-semantics","基线、冷却与队列","Baselines, cooldown and queue","首次采样与数据缺失后的恢复只建立基线，不立刻弹出。每条规则独立冷却；持续满足阈值时可在冷却结束后再次触发。满足规则会按当前实例队列呼出下一项，空队列使用当前方案。规则只在非持续显示模式生效。","Initial and recovered samples establish a baseline without popping up. Each rule has its own cooldown; a sustained threshold can trigger again after it expires. Matching rules summon the next item in that instance's queue, or the active profile for an empty queue. Rules work only in transient mode."),
            B("rule-examples","两个常用例子","Two useful examples","高负载提醒：变量 cpu.usage，阈值 >= 90，冷却 30 秒。换歌提醒：变量 media.title，模式“取值变化”，冷却按需求设置。先确保变量能读到有效数据，再配置触发规则。","High load: cpu.usage, Threshold >= 90, cooldown 30 seconds. Track changes: media.title with Change mode and a suitable cooldown. Confirm that the variable returns valid data before relying on a trigger.")),
        C("special","时间、网络与帧率方案","Time, network & FPS profiles","按方案类型调整专用参数。","Adjust the options specific to each profile.",
            B("time","时区与每日目标时间","Time zone and daily target","普通时钟使用本地时间；世界时钟可选固定 UTC 偏移，不自动跟随夏令时。每日目标模式显示距离下一个目标时刻的剩余比例；目标也按所选时区计算。关闭目标模式时显示当天已过进度。","Ordinary clocks use local time. World Clock uses a fixed UTC offset without automatic DST. Daily-target mode shows the remaining fraction until the next target time in the chosen zone; with it off, it shows elapsed day progress.",target:"hud"),
            B("network","网速单位与圆环参考值","Traffic units and ring reference","网络方案可选择自动字节单位或 Mbps；1 MB/s 等于 8 Mbps。圆环可以按总量、下载、上传或较大方向计算，再与参考带宽比较。参考值决定何时达到 100%，不会限制或测速网络本身。","Network profiles can use automatic byte units or Mbps; 1 MB/s equals 8 Mbps. The ring compares total, download, upload or the larger direction with your reference bandwidth. The reference sets the 100% scale and does not limit or benchmark the network."),
            B("probe","网络探测目标与协议","Probe targets and protocols","探测支持主机名、IPv4 和 IPv6。ICMP 不使用端口；TCP/UDP 使用设置的端口。探测失败只说明该目标/协议未成功响应，不能直接推断整台电脑断网；某些服务器会屏蔽 ICMP 或不回复 UDP。","Targets may be hostnames, IPv4 or IPv6. ICMP ignores the port; TCP/UDP use it. Failure means that target/protocol did not respond successfully, not necessarily that the whole PC is offline. Servers may block ICMP or not reply to UDP."),
            B("fps","帧率与显卡目标","FPS and GPU targets","帧率方案先刷新窗口/显示器列表，再选目标，按需要设置 100% 帧率。窗口统计所属进程的主交换链，显示器统计其主呈现流；它不是固定刷新率。缺少帧事件或权限时会显示状态，必要时以管理员身份运行。普通 GPU 方案可独立选择显卡；硬件传感器变量则指向其标明的具体设备。","Refresh and select a window/display target, then set the full-scale FPS. Window FPS uses the process's dominant swap chain; display FPS uses its dominant presentation stream, not the fixed refresh rate. Missing events or permissions produce status information; administrator access may be needed. Ordinary GPU profiles can select an adapter, while raw sensor keys identify their stated device.")),
        C("media","媒体信息与播放进度","Media information & progress","把系统媒体会话显示到 HUD。","Display a Windows media session in the HUD.",
            B("media-template","一套媒体模板","A media HUD template","Windows 媒体变量读取播放器注册到系统的媒体会话。可将曲名/歌手作为主值、播放时间作为次值，圆环变量设为 media.progress，量程设 0–100。","Windows media variables read sessions registered by a player. Use title/artist as the primary text, times as secondary text, and media.progress for a 0–100 ring.",code:"{media.title_artist}\n{media.position_text} / {media.duration_text}\n{media.status}",target:"variables"),
            B("media-state","暂停、直播与未提供的字段","Paused, live and missing fields","播放时进度按系统时间轴和播放速度更新；暂停时不外推。直播或未提供时长的会话没有有效百分比，显示 --。播放器未注册会话、没有歌手或专辑等元数据时，相应字段也会不可用。","Playing progress follows the reported timeline and rate; paused timelines do not extrapolate. Live sessions without a duration have no valid percentage and show --. Players without registered sessions or missing artist/album metadata leave those fields unavailable.")),
        C("instances","实验性多 HUD","Experimental multiple HUDs","让不同位置显示各自的方案与数据。","Give each HUD its own content and position.",
            B("instances-create","开启与选择实例","Enable and select instances","在实验性功能中启用多 HUD，添加并命名副 HUD，选择要编辑的实例。被选中的 HUD 会高亮便于定位；新增实例先保存并应用，再使用其预览。删除副实例不会删除主 HUD。","Enable multiple HUDs under Experimental Features, add/name a secondary HUD and select it for editing. The selected HUD is highlighted. Save & Apply a new instance before previewing it. Removing a secondary instance does not remove the primary HUD.",target:"experimental"),
            B("instances-scope","独立设置与共享设置","Independent and shared settings","方案、位置、轮播队列、触发规则和热区按实例配置。点击切换哪个 HUD，就推进它自己的队列。采样间隔、全局快捷键与点击切换总设置由所有 HUD 共用。编辑完成后保存并应用整套配置。","Profiles, positions, queues, trigger rules and hot zones belong to each instance. Clicking a HUD advances only its queue. Sampling interval, global shortcut and the click-cycling master setting are shared. Save & Apply commits the whole configuration.")),
        C("maintenance","配置、备份与维护","Configuration, backup & maintenance","保存自己的配置，并在出错时定位原因。","Keep your configuration and inspect failures.",
            B("backup","导出、导入与备份","Export, import and backup","在“关于 → 配置与维护”导出配置或创建备份；导入用于恢复整套设置。建议在大幅调整前先备份。API Key 等受当前用户加密保护的数据，换机器或账户后可能需要重新填写。","Export settings or create a backup under About → Configuration & Maintenance. Import restores a complete setup. Back up before substantial edits. Secrets encrypted for the current user may need re-entry on a different machine or account.",target:"about"),
            B("logs","日志与重置","Logs and reset","配置文件夹可从窗口右上角打开，日志文件夹可在关于页打开。排查时同时保留数据源状态或硬件诊断。恢复默认值会载入初始参数；确认后仍需保存并应用，才替换运行中的设置。","Open the config folder from the top bar and the logs folder from About. Keep source status or hardware diagnostics when troubleshooting. Reset loads first-run defaults; Save & Apply commits them to the running app."),
            B("updates","检查更新","Check for updates","关于页显示当前版本、架构及更新检查结果。无法获取线上版本或网络超时不等于已经是最新版；查看具体状态后再重试。开发包与公开发布的版本号可能相同，应结合实际交付说明判断。","About shows the version, architecture and update-check result. A network failure or unavailable remote version does not confirm that you are up to date. Check the status and retry. Development packages may retain the public version number; use their delivery notes to identify them.")),
        C("troubleshooting","常见问题与提示","Troubleshooting & warnings","按现象快速定位到对应设置。","Use the symptom to find the right setting.",
            B("not-visible","HUD 为什么没出现","Why the HUD is not visible","先检查总开关和快捷键隐藏状态，再确认是常驻还是临时模式。临时模式需要事件、热区或规则呼出；检查目标显示器、坐标、透明度和热区开关。只有保存方案而没有保存并应用时，运行中的 HUD 可能仍使用旧设置。","Check the Master Switch and shortcut suppression, then confirm persistent vs. transient mode. Transient mode needs an event, hot zone or rule. Check the target display, coordinates, opacity and hot-zone switch. Saving a profile without Save & Apply can leave the running HUD on its old settings.",target:"display"),
            B("missing-data","--、无效表达式与单位","--, invalid expressions and units","-- 表示数据没有有效读数或表达式无法计算。先到变量库确认含义和单位，再检查硬件驱动、API 鉴权、JSON 路径或帧率采集状态。显示格式不能把缺失的数据修复成真实测量值；MB/s、Mbps、GiB、°C 等单位也不能混用。","-- means no valid reading or an expression failure. Check meaning and units in the library, then the driver, API authentication, JSON path or FPS status. Formatting cannot turn missing data into a real measurement. Keep MB/s, Mbps, GiB and °C distinct.",target:"variables"),
            B("ignore-warning","“此数据不再提示”的范围","Scope of Don't warn about this data again","勾选只永久关闭当前提示窗口已经列出的变量；其他变量仍会提示。普通关闭只确认这次故障。多个 HUD 的故障可能合并在同一窗口；表达式错误按具体方案与表达式区分。勾选不会修复数据源，也不会停止采集。","The checkbox permanently silences only the variables already listed in the current warning window. Other variables still warn. Closing normally acknowledges that incident. Multiple HUDs can share one warning window; expression faults are distinguished by profile and expression. Suppression does not repair or stop collection."))
    };
}
